//! ↩️ reorder-cameras leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfCamera;
use crate::artifacts::gltf::schema::mutations::reorder_cameras::mutation::{validate, GltfReorderCamerasPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{cameras_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.reorder-cameras.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfReorderCamerasInverseOperation { Insert { position: usize, item: GltfCamera }, Delete { index: usize, removed: GltfCamera }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderCamerasInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderCamerasPayload, pub operation: GltfReorderCamerasInverseOperation }
async fn operation(payload: &GltfReorderCamerasPayload, base: &GltfSnapshot) -> GltfReorderCamerasInverseOperation { GltfReorderCamerasInverseOperation::Reorder { order: (0..payload.order.len()).map(|index| payload.order.iter().position(|value| *value == index).unwrap()).collect() } }
async fn touched_paths(payload: &GltfReorderCamerasPayload) -> Vec<String> { payload.order.iter().map(|index| format!("document/cameras/{}", index)).chain(std::iter::empty()).collect() }
pub async fn validate_inverse(inverse: &GltfReorderCamerasInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub async fn apply_inverse(inverse: &GltfReorderCamerasInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfReorderCamerasInverseOperation::Insert { position, .. } if *position > after.document.cameras.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/cameras", "position must be within the collection")), GltfReorderCamerasInverseOperation::Delete { index, .. } if *index >= after.document.cameras.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/cameras", "index must address an item")), GltfReorderCamerasInverseOperation::Move { index, position } if *index >= after.document.cameras.len() || *position >= after.document.cameras.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/cameras", "indices must address items")), GltfReorderCamerasInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.cameras.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.cameras.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/cameras", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfReorderCamerasInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Cameras, &Change::Insert(*position))?; next.document.cameras.insert(*position, item.clone());  }, GltfReorderCamerasInverseOperation::Delete { index, .. } => { cameras_op(&mut next, GltfTopLevelFamily::Cameras, *index, None, None)?;  }, GltfReorderCamerasInverseOperation::Move { index, position } => { cameras_op(&mut next, GltfTopLevelFamily::Cameras, *index, Some(*position), None)?;  }, GltfReorderCamerasInverseOperation::Reorder { order } => { cameras_op(&mut next, GltfTopLevelFamily::Cameras, order[0], None, Some(order))?;  } } Ok(next) }
pub async fn encode(inverse: &GltfReorderCamerasInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub async fn derive(payload: &GltfReorderCamerasPayload, base: &GltfSnapshot) -> Result<GltfReorderCamerasInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfReorderCamerasInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
